80	export async function putRemoteObject(
81		complianceConfig: ComplianceConfig,
82		accountId: string,
83		bucketName: string,
84		objectName: string,
85		object: Readable | ReadableStream | Buffer,
86		options: Record<(typeof putHeaderKeys)[number], string | undefined>,
87		jurisdiction?: string,
88		storageClass?: string
89	): Promise<void> {
90		const headers: HeadersInit = {};
91		for (const key of putHeaderKeys) {
92			const value = options[key] || "";
93			if (value && typeof value === "string") {
94				headers[key] = value;
95			}
96		}
97		if (jurisdiction !== undefined) {
98			headers["cf-r2-jurisdiction"] = jurisdiction;
99		}
100	
101		if (storageClass !== undefined) {
102			headers["cf-r2-storage-class"] = storageClass;
103		}
104	
105		const result = await fetchR2Objects(
106			complianceConfig,
107			`/accounts/${accountId}/r2/buckets/${bucketName}/objects/${objectName}`,
108			{
109				body: object,
110				headers,
111				method: "PUT",
112				duplex: "half",
113			}
114		);
115		if (result === null) {
116			throw new UserError("The specified bucket does not exist.");
117		}
118	}
