113		queryParams?: URLSearchParams
114	): Promise<ResponseType[]> {
115		const results: ResponseType[] = [];
116		let getMoreResults = true;
117		let page = 1;
118		while (getMoreResults) {
119			queryParams = new URLSearchParams(queryParams);
120			queryParams.set("page", String(page));
121	
122			const { response: json, status } = await fetchInternal<
123				FetchResult<ResponseType[]>
124			>(complianceConfig, resource, init, queryParams);
125			if (json.success) {
126				results.push(...json.result);
127				if (hasMorePages(json.result_info)) {
128					page = page + 1;
129				} else {
130					getMoreResults = false;
131				}
132			} else {
133				throwFetchError(resource, json, status);
134			}
135		}
136		return results;
137	}
