188	interface PageResultInfo {
189		page: number;
190		per_page: number;
191		count: number;
192		total_count: number;
193	}
194	
195	export function hasMorePages(
196		result_info: unknown
197	): result_info is PageResultInfo {
198		const page = (result_info as PageResultInfo | undefined)?.page;
199		const per_page = (result_info as PageResultInfo | undefined)?.per_page;
200		const total = (result_info as PageResultInfo | undefined)?.total_count;
201	
202		return (
203			page !== undefined &&
204			per_page !== undefined &&
205			total !== undefined &&
206			page * per_page < total
207		);
208	}
209	
210	function throwFetchError(
211		resource: string,
212		response: FetchResult<unknown>,
213		status: number
214	): never {
215		// This is an error from within an MSW handler
216		if (typeof vitest !== "undefined" && !("errors" in response)) {
217			throw response;
218		}
219		for (const error of response.errors) {
220			maybeThrowFriendlyError(error);
221		}
222	
223		const error = new APIError({
224			text: `A request to the Cloudflare API (${resource}) failed.`,
225			notes: [
226				...response.errors.map((err) => ({ text: renderError(err) })),
227				...(response.messages?.map((text) => ({ text })) ?? []),
228			],
229			status,
230		});
231		// add the first error code directly to this error
232		// so consumers can use it for specific behaviour
233		const code = response.errors[0]?.code;
234		if (code) {
235			error.code = code;
236		}
237		// extract the account tag from the resource (if any)
238		error.accountTag = extractAccountTag(resource);
239		throw error;
240	}
241	
242	export function extractAccountTag(resource: string) {
243		const re = new RegExp("/accounts/([a-zA-Z0-9]+)/?");
244		const matches = re.exec(resource);
245		return matches?.[1];
246	}
247	
248	function hasCursor(result_info: unknown): result_info is { cursor: string } {
249		const cursor = (result_info as { cursor: string } | undefined)?.cursor;
250		return cursor !== undefined && cursor !== null && cursor !== "";
251	}
