[metadata] {"type": "create", "filePath": "/workspace/repo/packages/wrangler/src/r2/helpers/data-catalog.ts", "content": "import { APIError } from "@cloudflare/workers-utils";
import { confirm } from "../../dialogs";
import { logger } from "../../logger";

/**
 * Header sent on R2 write requests to ask the API to reject the operation
 * (with {@link DATA_CATALOG_CONFLICT_ERROR_CODE}) when a data catalog is
 * enabled for the bucket, so that we can warn the user before proceeding.
 */
export const DATA_CATALOG_CHECK_HEADER = "cf-r2-data-catalog-check";

/**
 * API error code returned (alongside HTTP 409) when a write is rejected
 * because a data catalog is enabled for the bucket.
 */
export const DATA_CATALOG_CONFLICT_ERROR_CODE = 10081;

const DATA_CATALOG_CONFLICT_PROMPT =
	"Data catalog is enabled for this bucket. Proceeding may leave the data catalog in an invalid state. Continue?";

/**
 * Prompt shown up-front before a bulk upload when the data catalog check
 * cannot be performed per-request.
 */
export const BULK_PUT_CONFIRM_PROMPT =
	"Bulk upload may overwrite existing objects. If this bucket has data catalog enabled, this operation could leave the catalog in an invalid state. Continue?";

/**
 * Returns whether the given error is the R2 data catalog conflict (HTTP 409,
 * error code 10081) surfaced by the API when a data catalog is enabled.
 */
export function isDataCatalogConflict(err: unknown): boolean {
	return (
		err instanceof APIError && err.code === DATA_CATALOG_CONFLICT_ERROR_CODE
	);
}

/**
 * Runs a write operation that may trigger the R2 data catalog safety check.
 *
 * When `force` is false, the operation is first attempted with the data
 * catalog check enabled. If the API rejects the request because a data catalog
 * is enabled (HTTP 409, error code 10081), the user is prompted before the
 * operation is retried without the check. When `force` is true, the operation
 * runs directly without the check.
 *
 * @returns `true` if the operation completed, `false` if the user cancelled.
 */
export async function withDataCatalogCheck(
	force: boolean,
	perform: (dataCatalogCheck: boolean) => Promise<void>
): Promise<boolean> {
	const dataCatalogCheck = !force;
	try {
		await perform(dataCatalogCheck);
		return true;
	} catch (e) {
		if (dataCatalogCheck && isDataCatalogConflict(e)) {
			const proceed = await confirm(DATA_CATALOG_CONFLICT_PROMPT);
			if (!proceed) {
				logger.log("Operation cancelled.");
				return false;
			}
			await perform(false);
			return true;
		}
		throw e;
	}
}
